!function(){"use strict";const e={falls:{title:"Dhuandhar Falls Plunge Rim (30m Drop)",sub:"Main Waterfall Drop & Misty Plunge Basin",desc:"Where the Narmada River narrows dramatically into a rock chasm and drops 30 meters. The sheer impact generates perpetual mist clouds resembling smoke (Dhuan).",loc:"Bhedaghat, Jabalpur (35 km)",river:"Narmada River Main Channel",high:"30m Plunge, East Promenade View"},canyon:{title:"Bhedaghat Marble Rocks Canyon (3 km)",sub:"Magnesium Limestone Cliffs & Boating Stretch",desc:"A 3-kilometer stretch of towering 100-foot white, cream, and blue-tinted marble cliffs carved over millennia. Popular for rowboat tours, especially during full moon nights.",loc:"Panchvati Ghat to Bandar Kudini",river:"Narmada Gorge",high:"Rowboat tours, Moonlight vistas"},ropeway:{title:"Overhead Cable Ropeway Line",sub:"Aerial Viewpoint Across Narmada River",desc:"Connects the East and West banks of Bhedaghat gorge, taking tourists high above the roaring waterfall rim for panoramic aerial photography.",loc:"East Bank to West Bank Span",river:"Narmada Gorge Crossing",high:"360-degree aerial panorama"},temple:{title:"Chausath Yogini Temple (10th Century)",sub:"Kalachuri Dynasty Heritage Site",desc:"Perched on a hilltop overlooking the Narmada River, this ancient circular shrine houses 64 hand-carved stone Yogini images and a Gauri-Shankar temple.",loc:"Hilltop above Bhedaghat",river:"Overlooking Narmada Basin",high:"Ancient Kalachuri sculpture & river vistas"}},t={monsoon:{title:"Monsoon Roaring Spray (July – October)",desc:"The Narmada River swells dramatically with rainwater. Water gushes through the marble notch with immense kinetic energy, producing towering mist plumes. Boating is suspended for safety, but ropeway and promenade views are spectacular.",flow:"Flow: Heavy High-Volume Torrent",boat:"Boating: Suspended due to high currents",highlight:"Highlight: Cable Car Aerial View & Mist Plumes"},winter:{title:"Winter Moonlight Boating (November – March)",desc:"Cool temperatures and calm emerald-blue waters make winter the peak tourist season. Guided rowboat trips navigate through 100ft white marble cliffs, specially during Sharad Purnima full moon nights.",flow:"Flow: Moderate Clear Blue Flow",boat:"Boating: Full rowboat operations at Panchvati Ghat",highlight:"Highlight: Full Moon Night Boating & Marble Glow"},summer:{title:"Summer Crystal Clarity (April – June)",desc:"Water levels drop, revealing intricate water-carved marble formations, pothole erosion, and ancient rock strata along the riverbed.",flow:"Flow: Low Water Level",boat:"Boating: Morning and evening boat rides",highlight:"Highlight: Geological Rock Strata Inspection"}};document.addEventListener("DOMContentLoaded",function(){const a=document.querySelectorAll(".river-pin"),n=document.getElementById("spot-title"),o=document.getElementById("spot-sub"),i=document.getElementById("spot-body"),r=document.getElementById("spot-loc"),l=document.getElementById("spot-river"),s=document.getElementById("spot-high"),c=document.querySelectorAll(".season-btn"),d=document.getElementById("s-card-title"),h=document.getElementById("s-card-desc"),g=document.getElementById("sp-flow"),m=document.getElementById("sp-boat"),u=document.getElementById("sp-highlight"),p=document.getElementById("theme-toggle");p&&p.addEventListener("click",function(){document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");localStorage.setItem("theme",e?"light":"dark")}),a.forEach(function(t){t.addEventListener("click",function(){const a=t.getAttribute("data-spot"),c=e[a];c&&(n&&(n.textContent=c.title),o&&(o.textContent=c.sub),i&&(i.innerHTML=`<p>${c.desc}</p>`),r&&(r.textContent=c.loc),l&&(l.textContent=c.river),s&&(s.textContent=c.high))})}),c.forEach(function(e){e.addEventListener("click",function(){c.forEach(e=>e.classList.remove("active")),e.classList.add("active");const a=e.getAttribute("data-season"),n=t[a];n&&(d&&(d.textContent=n.title),h&&(h.textContent=n.desc),g&&(g.textContent=n.flow),m&&(m.textContent=n.boat),u&&(u.textContent=n.highlight))})});const v=document.getElementById("menu-toggle"),b=document.getElementById("nav-menu");v&&b&&v.addEventListener("click",()=>b.classList.toggle("active"))})}();